edge_probe_source:
extends Node3D
func total(inv: InventoryState, id: StringName) -> int:
	var result := 0
	for item in inv.get_items():
		if item.definition_id == id: result += item.quantity
	return result
func request_for(profile: ProfileState) -> SortieRequest:
	var ids: Array[String] = []
	for item in profile.inventory.get_items():
		if item.definition_id in [&"ammo.556_standard", &"ammo.rocket_standard"]: ids.append(item.instance_id)
	return profile.create_sortie_request(SortieRequest.PROTOTYPE_AREA_ID, SortieRequest.PROTOTYPE_MISSION_ID, ids)
func _ready() -> void:
	await get_tree().process_frame
	var result := {"user_data_dir": OS.get_user_data_dir()}
	var profile := ProfileState.create_new()
	var before := total(profile.inventory, &"ammo.556_standard")
	var rockets_before := total(profile.inventory, &"ammo.rocket_standard")
	var session := SortieSession.create_from_profile(request_for(profile),profile)
	session.activate()
	result["immediate_extraction"] = session.complete_extraction()
	var outcome := SortieOutcomeService.create_outcome(session)
	SortieOutcomeService.commit_outcome(profile,outcome)
	result["zero_shot_roundtrip"] = {"rifle_before":before,"rifle_after":total(profile.inventory,&"ammo.556_standard"),"rocket_before":rockets_before,"rocket_after":total(profile.inventory,&"ammo.rocket_standard")}
	var player := load("res://scenes/player/player.tscn").instantiate() as PlayerController
	player.configure_loadout(profile.inventory,profile.loadout)
	add_child(player)
	await get_tree().process_frame
	var light_damage := player.receive_damage(DamagePacket.new(25.0))
	player.equip_armor(ContentDB.get_item(&"armor.bulwark_plate_01") as EquipmentDefinition)
	var heavy_damage := player.receive_damage(DamagePacket.new(25.0))
	result["armor_damage"] = {"light":light_damage,"heavy":heavy_damage}
	player.queue_free()
	await get_tree().process_frame
	profile = ProfileRuntime.new_profile()
	result["large_ammo_stock_added"] = profile.inventory.add_item(ItemInstance.new(&"ammo.556_standard",10000))
	result["large_stock_profile_valid"] = profile.validate()
	result["overweight_sortie_created"] = SortieSession.create_from_profile(request_for(profile),profile) != null
	var hideout = load("res://scenes/presentation/slice/hideout.tscn").instantiate()
	add_child(hideout)
	hideout.show_section("Operations")
	hideout._deploy()
	result["hideout_ui_visible_after_failed_deploy"] = hideout.ui.visible
	result["failed_deploy_created_session"] = SortieRuntime.get_current_session() != null
	hideout.queue_free()
	await get_tree().process_frame
	var f := FileAccess.open(OS.get_environment("BUNNY_EVIDENCE").path_join("edge_probe.json"),FileAccess.WRITE)
	f.store_string(JSON.stringify(result,"  ")); f.close()
	print("AUDIT_EDGE_PROBE ",JSON.stringify(result))
	var bad_save := FileAccess.open("user://profile.json",FileAccess.WRITE)
	bad_save.store_string("{broken"); bad_save.close()
	AudioDirector.shutdown_for_test()
	await get_tree().create_timer(0.3).timeout
	get_tree().quit()
